void Window::error(QString text){_error->setText(text);_error->setVisible(!text.isEmpty());}
void Window::cancelLogin(){++_loginGeneration;_qrTimer.stop();_qr={};if(!_challenge.isEmpty())_api->request("/auth/desktop/cancel",QJsonObject{{"challenge_id",_challenge.value("challenge_id")},{"client_secret",_pendingRequest.value("client_secret")}},[](ApiResult){},false);_challenge={};_pendingRequest={};_phoneBusy=false;_code->clear();error({});}
void Window::beginQr(){cancelLogin();_loginPages->setCurrentIndex(1);_qrImage->clear();_qrStatus->setText("Создание QR-кода…");int generation=_loginGeneration;
 _api->request("/auth/qr/request",QJsonObject{{"platform","windows"}},[this,generation](ApiResult result){if(generation!=_loginGeneration)return;if(!result.ok()){error(result.error);return;}_qr=result.value.toObject();_qrDeadline=QDateTime::currentMSecsSinceEpoch()+_qr.value("expires_in").toInt()*1000;_qrImage->setPixmap(QPixmap::fromImage(loginQr(_qr.value("qr_text").toString(),4)));_qrStatus->setText("Сканируйте QR и подтвердите вход на телефоне");pollQr(generation);},false);
}
void Window::pollQr(int generation){if(generation!=_loginGeneration||_qr.isEmpty())return;if(QDateTime::currentMSecsSinceEpoch()>=_qrDeadline){_qrStatus->setText("QR истёк. Нажмите «Обновить QR»");return;}
 _api->request("/auth/qr/poll",QJsonObject{{"id",_qr.value("id")},{"poll_token",_qr.value("poll_token")}},[this,generation](ApiResult result){if(generation!=_loginGeneration)return;if(result.ok()){auto value=result.value.toObject();if(value.contains("token")){_qrTimer.stop();_api->acceptSession(value);return;}auto state=value.value("status").toString();if(state=="expired"||state=="rejected"||state=="used"){_qrStatus->setText("Попытка завершена. Обновите QR");return;}_qrStatus->setText(state=="scanned"?"Подтвердите вход в Волну на телефоне":"Сканируйте QR и подтвердите вход на телефоне");}else error(result.error);_qrTimer.start(result.status==429?int(std::min(result.retryMs,qint64(300000))):result.ok()?1000:3000);},false);
}
void Window::requestCode(){if(_phoneBusy||QDateTime::currentMSecsSinceEpoch()<_retryAt)return;auto phone=_phone->text();phone.remove(QRegularExpression("[\\s()-]"));if(!QRegularExpression("^\\+[1-9][0-9]{7,14}$").match(phone).hasMatch()){error("Введите номер с кодом страны, например +7 900 123-45-67");return;}
 if(_pendingRequest.isEmpty()||_pendingRequest.value("phone").toString()!=phone)_pendingRequest={{"phone",phone},{"request_id",Api::nonce(24)},{"client_secret",Api::nonce()}};
 _phoneBusy=true;_requestCode->setEnabled(false);error({});auto generation=_loginGeneration;
 _api->request("/auth/desktop/request",_pendingRequest,[this,generation](ApiResult result){if(generation!=_loginGeneration)return;_phoneBusy=false;if(!result.ok()){if(result.status==429)_retryAt=QDateTime::currentMSecsSinceEpoch()+result.retryMs;error(result.error);return;}_challenge=result.value.toObject();_codeDeadline=QDateTime::currentMSecsSinceEpoch()+_challenge.value("expires_in").toInt(300)*1000;_retryAt=QDateTime::currentMSecsSinceEpoch()+std::max(qint64(0),_challenge.value("resend_available_at").toVariant().toLongLong()-_challenge.value("server_time").toVariant().toLongLong());_loginPages->setCurrentIndex(3);_code->clear();_code->setFocus();},false);
}
void Window::verifyCode(){if(_phoneBusy||_challenge.isEmpty())return;if(!QRegularExpression("^[0-9]{6}$").match(_code->text()).hasMatch()){error("Введите шесть цифр из служебного сообщения");return;}_phoneBusy=true;_verify->setEnabled(false);auto generation=_loginGeneration;error({});
 _api->request("/auth/desktop/verify",QJsonObject{{"challenge_id",_challenge.value("challenge_id")},{"client_secret",_pendingRequest.value("client_secret")},{"code",_code->text()}},[this,generation](ApiResult result){if(generation!=_loginGeneration)return;_phoneBusy=false;if(!result.ok()){error(result.error);return;}_challenge={};_pendingRequest={};_code->clear();_api->acceptSession(result.value.toObject());},false);
}
void Window::loggedIn(){_userId=_api->session().value("user").toObject().value("id").toVariant().toLongLong();_root->setCurrentIndex(1);_qrTimer.stop();++_loginGeneration;_phone->clear();_code->clear();error({});if(!_calls){_calls=new Calls(_api,this);connect(_calls,&Calls::problem,this,&Window::error);connect(_calls,&Calls::attachmentReady,this,[this](QJsonObject attachment){if(!_pendingSend.isEmpty()){error("Сначала повторите предыдущую отправку");return;}_pendingChat=attachment.value("native_chat_id").toVariant().toLongLong();if(_pendingChat<1)return;_pendingSend={{"text",""},{"attachment_id",attachment.value("id")},{"client_id",QUuid::createUuid().toString(QUuid::WithoutBraces)}};postPending();});connect(_calls->findChild<CallBridge*>(),&CallBridge::recordingChanged,this,[this](bool active){_recording=active;_voice->setText(active?"■":"●");_voice->setToolTip(active?"Завершить запись":"Записать голосовое сообщение");});}
 refreshChats();_api->startEvents();_presenceTimer.start();_chatRefreshTimer.start();presence();if(!SessionStore::persistentAvailable())error("Проверочная сборка Linux: сеанс хранится только в памяти. Windows использует защищённое хранилище");
}
void Window::refreshChats(){if(!_userId||_refreshChatsBusy)return;_refreshChatsBusy=true;_api->request("/chats",noData(),[this](ApiResult result){_refreshChatsBusy=false;if(!result.ok()){error(result.error);return;}_chatRows=result.value.toArray();showChats();if(_chatId){for(const auto &value:_chatRows){auto chat=value.toObject();if(chat.value("id").toVariant().toLongLong()==_chatId){_chat=chat;_chatTitle->setText(chat.value("name").toString());_chatSubtitle->setText(chat.value("peer_online").toBool()?"в сети":chat.value("kind").toString()=="direct"?"не в сети":chat.value("kind").toString()=="group"?"Группа":"");break;}}}});}
void Window::showChats(){_chats->clear();for(auto value:_chatRows){auto chat=value.toObject();QString name=chat.value("name").toString();if(!name.contains(_filter->text(),Qt::CaseInsensitive)&&!chat.value("last_text").toString().contains(_filter->text(),Qt::CaseInsensitive))continue;auto row=new QListWidgetItem;row->setData(Qt::UserRole,chat.value("id").toVariant());row->setText(name+(chat.value("unread").toInt()?QString("    %1").arg(chat.value("unread").toInt()):QString())+"\n"+chat.value("last_text").toString().left(45));row->setSizeHint({250,66});_chats->addItem(row);if(chat.value("id").toVariant().toLongLong()==_chatId)_chats->setCurrentItem(row);}}
void Window::openChat(qint64 id){if(_recording){error("Сначала завершите запись голосового");return;}if(_chatId)_drafts[_chatId]=_editor->toPlainText();_chatId=id;_messageRows.clear();_messages->clear();_historyBusy=false;_exhausted=false;++_historyGeneration;for(auto value:_chatRows)if(value.toObject().value("id").toVariant().toLongLong()==id)_chat=value.toObject();_chatTitle->setText(_chat.value("name").toString());_chatSubtitle->setText(_chat.value("peer_online").toBool()?"в сети":"");bool send=_chat.value("can_send").toInt(1)!=0;_editor->setEnabled(send);_send->setEnabled(send);_attach->setEnabled(send);_voice->setEnabled(send);bool call=_chat.value("kind").toString()=="direct"&&_chat.value("peer_id").toVariant().toLongLong()!=_userId;_audio->setEnabled(call);_video->setEnabled(call);_editor->setPlainText(_drafts.value(id));_empty->hide();loadHistory();}
void Window::loadHistory(bool older){if(!_chatId||_historyBusy||older&&_exhausted)return;_historyBusy=true;const auto generation=_historyGeneration;QString path="/chats/"+QString::number(_chatId)+"/messages";if(older&&!_messageRows.isEmpty())path+="?before="+QString::number(_messageRows.firstKey());
 _api->request(path,noData(),[this,generation,older](ApiResult result){if(generation!=_historyGeneration)return;_historyBusy=false;if(!result.ok()){error(result.error);return;}auto rows=result.value.toArray();if(older||_messageRows.isEmpty())_exhausted=rows.size()<50;for(auto value:rows){auto message=value.toObject();_messageRows[message.value("id").toVariant().toLongLong()]=message;}renderMessages(older);_older->setVisible(!_exhausted);if(!_messageRows.isEmpty()&&isActiveWindow())_api->request("/chats/"+QString::number(_chatId)+"/read",QJsonObject{{"message_id",_messageRows.lastKey()}},[](ApiResult){});});}
void Window::renderMessages(bool preserve){auto scroll=_messages->verticalScrollBar();const auto oldValue=scroll->value(),oldMax=scroll->maximum();bool bottom=oldValue>=oldMax-40;_messages->clear();QString previousDate;
 for(auto it=_messageRows.cbegin();it!=_messageRows.cend();++it){auto message=it.value();auto date=QDateTime::fromString(message.value("created_at").toString(),Qt::ISODate).toLocalTime().date().toString("d MMMM yyyy");if(date!=previousDate){auto day=new QListWidgetItem(date,_messages);day->setTextAlignment(Qt::AlignCenter);day->setForeground(_theme.color("windowSubTextFg"));day->setSizeHint({200,36});previousDate=date;}
 auto item=new QListWidgetItem(_messages);item->setData(Qt::UserRole,it.key());auto row=new QWidget;auto outer=new QHBoxLayout(row);outer->setContentsMargins(8,1,8,1);bool mine=message.value("sender_id").toVariant().toLongLong()==_userId;auto bubble=new QWidget;auto content=new QVBoxLayout(bubble);content->setContentsMargins(12,8,12,7);content->setSpacing(5);bubble->setMaximumWidth(530);auto color=_theme.color(mine?"msgOutBg":"msgInBg",_theme.color("windowBg")).name();bubble->setStyleSheet("QWidget{background:"+color+";border-radius:12px;}");if(!mine){auto name=label(message.value("sender_name").toString());name->setStyleSheet("color:#6ab3f3;font-weight:600");content->addWidget(name);}auto text=label(message.value("deleted_at").isNull()||!message.contains("deleted_at")?message.value("text").toString():"Сообщение удалено");text->setTextInteractionFlags(Qt::TextSelectableByMouse|Qt::TextSelectableByKeyboard);text->setMaximumWidth(490);text->setSizePolicy(QSizePolicy::Preferred,QSizePolicy::Preferred);if(!text->text().isEmpty())content->addWidget(text);
 auto attachment=message.value("attachment").toObject();if(!attachment.isEmpty()&&message.value("deleted_at").isNull()){auto file=button("↧ "+attachment.value("name").toString()+QString(" · %1 КБ").arg((attachment.value("size").toInt()+1023)/1024),"file");file->setMaximumWidth(480);content->addWidget(file);connect(file,&QPushButton::clicked,this,[this,message]{openFile(message);});}
 auto time=label(when(message.value("created_at").toString())+(mine?"  ✓":""),"subtitle");time->setAlignment(Qt::AlignRight);content->addWidget(time);if(mine)outer->addStretch();outer->addWidget(bubble);if(!mine)outer->addStretch();row->adjustSize();item->setSizeHint({100,row->sizeHint().height()});_messages->setItemWidget(item,row);
 }
 if(preserve)scroll->setValue(oldValue+(scroll->maximum()-oldMax));else if(bottom)scroll->setValue(scroll->maximum());
}
void Window::sendMessage(QString attachment){if(_recording){error("Завершите запись и дождитесь загрузки голосового");return;}if(!_pendingSend.isEmpty()){postPending();return;}if(!_chatId)return;auto text=_editor->toPlainText();if(text.trimmed().isEmpty()&&attachment.isEmpty())return;if(text.size()>4000){error("Максимум 4000 символов");return;}_pendingChat=_chatId;_pendingSend={{"text",text},{"client_id",QUuid::createUuid().toString(QUuid::WithoutBraces)}};if(!attachment.isEmpty())_pendingSend.insert("attachment_id",attachment);postPending();}
void Window::postPending(){if(_sendBusy||_pendingSend.isEmpty())return;_sendBusy=true;_send->setEnabled(false);_editor->setReadOnly(true);auto chat=_pendingChat;_api->request("/chats/"+QString::number(chat)+"/messages",_pendingSend,[this,chat](ApiResult result){_sendBusy=false;_send->setEnabled(true);_editor->setReadOnly(false);if(!result.ok()){_send->setText("Повторить отправку");error(result.error+". Повтор использует тот же идентификатор и не создаёт дубликат");return;}_send->setText("Отправить");_pendingSend={};_pendingChat=0;_drafts.remove(chat);if(chat==_chatId){_editor->clear();auto message=result.value.toObject();_messageRows[message.value("id").toVariant().toLongLong()]=message;renderMessages();}_api->retrySave();refreshChats();});}
void Window::attachFile(){if(_recording){error("Завершите запись и дождитесь загрузки голосового");return;}if(!_pendingSend.isEmpty()){error("Сначала повторите предыдущую отправку");return;}auto file=QFileDialog::getOpenFileName(this,"Прикрепить файл");if(file.isEmpty())return;_attach->setEnabled(false);auto chat=_chatId;_api->upload(file,[this,chat](ApiResult result){_attach->setEnabled(true);if(!result.ok()){error(result.error);return;}if(chat!=_chatId){error("Чат изменился во время загрузки. Прикрепите файл заново");return;}sendMessage(result.value.toObject().value("id").toString());});}
void Window::openFile(QJsonObject message){auto attachment=message.value("attachment").toObject();_api->download(attachment.value("id").toString(),message.value("id").toVariant().toLongLong(),[this,attachment](ApiResult result){if(!result.ok()){error(result.error);return;}auto mime=attachment.value("mime").toString();if(mime.startsWith("audio/")||mime.startsWith("video/")){if(_calls)_calls->media(result.bytes,mime);return;}if(mime.startsWith("image/")){QImage image=QImage::fromData(result.bytes);if(!image.isNull()){auto dialog=new QDialog(this);dialog->setAttribute(Qt::WA_DeleteOnClose);dialog->setWindowTitle(attachment.value("name").toString());auto layout=new QVBoxLayout(dialog);auto picture=new QLabel;picture->setAlignment(Qt::AlignCenter);picture->setPixmap(QPixmap::fromImage(image).scaled(1000,740,Qt::KeepAspectRatio,Qt::SmoothTransformation));layout->addWidget(picture);dialog->resize(1020,780);dialog->show();return;}}
 auto path=QFileDialog::getSaveFileName(this,"Сохранить файл",QFileInfo(attachment.value("name").toString()).fileName());if(path.isEmpty())return;QSaveFile file(path);if(!file.open(QIODevice::WriteOnly)||file.write(result.bytes)!=result.bytes.size()||!file.commit())error("Не удалось сохранить файл");});}
void Window::messageMenu(QPoint point){auto item=_messages->itemAt(point);if(!item)return;auto message=_messageRows.value(item->data(Qt::UserRole).toLongLong());if(message.isEmpty())return;QMenu menu;auto copy=menu.addAction("Копировать текст");QAction *edit=nullptr,*remove=nullptr;if(message.value("sender_id").toVariant().toLongLong()==_userId){edit=menu.addAction("Изменить");remove=menu.addAction("Удалить у всех");}auto chosen=menu.exec(_messages->viewport()->mapToGlobal(point));if(chosen==copy)qApp->clipboard()->setText(message.value("text").toString());else if(edit&&chosen==edit){bool ok=false;auto text=QInputDialog::getMultiLineText(this,"Изменить сообщение","Текст",message.value("text").toString(),&ok);if(ok)_api->request("/messages/"+QString::number(message.value("id").toVariant().toLongLong())+"/edit",QJsonObject{{"text",text}},[this](ApiResult result){if(!result.ok())error(result.error);else loadHistory();});}else if(remove&&chosen==remove){if(QMessageBox::question(this,"Удалить сообщение?","Сообщение будет удалено у всех участников")!=QMessageBox::Yes)return;_api->request("/messages/"+QString::number(message.value("id").toVariant().toLongLong())+"/delete",QJsonObject{},[this](ApiResult result){if(!result.ok())error(result.error);else loadHistory();});}}
void Window::newChat(){bool ok=false;auto query=QInputDialog::getText(this,"Новый чат","Имя пользователя или полный номер телефона",QLineEdit::Normal,{},&ok);if(!ok||query.trimmed().isEmpty())return;_api->request("/users?q="+QString::fromLatin1(QUrl::toPercentEncoding(query)),noData(),[this](ApiResult result){if(!result.ok()){error(result.error);return;}auto people=result.value.toArray();if(people.isEmpty()){error("Пользователи не найдены");return;}QStringList names;for(auto value:people){auto user=value.toObject();names<<user.value("name").toString()+" (@"+user.value("username").toString()+")";}bool ok=false;auto name=QInputDialog::getItem(this,"Выберите собеседника","Пользователь",names,0,false,&ok);if(!ok)return;auto user=people.at(names.indexOf(name)).toObject();_api->request("/chats",QJsonObject{{"user_id",user.value("id")}},[this](ApiResult result){if(!result.ok()){error(result.error);return;}auto id=result.value.toObject().value("id").toVariant().toLongLong();_api->request("/chats",noData(),[this,id](ApiResult rows){if(rows.ok()){_chatRows=rows.value.toArray();showChats();openChat(id);}else error(rows.error);});});});}
void Window::presence(){if(!_userId)return;bool visible=!_quitting&&qApp->applicationState()==Qt::ApplicationActive&&((isVisible()&&!isMinimized()&&isActiveWindow())||(_calls&&_calls->isVisible()&&_calls->isActiveWindow()));_api->request("/presence",QJsonObject{{"client",_presenceClient},{"visible",visible},{"sequence",++_presenceSequence}},[](ApiResult){});if(visible&&!_messageRows.isEmpty())_api->request("/chats/"+QString::number(_chatId)+"/read",QJsonObject{{"message_id",_messageRows.lastKey()}},[](ApiResult){});}
void Window::receive(QJsonObject event){if(_calls)_calls->dispatch(event);auto type=event.value("type").toString();if(type=="message"||type=="message-update"){auto message=event.value("message").toObject();if(message.value("chat_id").toVariant().toLongLong()==_chatId){_messageRows[message.value("id").toVariant().toLongLong()]=message;renderMessages();if(isActiveWindow())_api->request("/chats/"+QString::number(_chatId)+"/read",QJsonObject{{"message_id",message.value("id")}},[](ApiResult){});}if(type=="message"&&event.value("notify").toBool(true)&&!isActiveWindow()&&message.value("sender_id").toVariant().toLongLong()!=_userId&&_tray)_tray->showMessage(message.value("sender_name").toString("Волна"),message.value("text").toString().left(120),QSystemTrayIcon::Information,5000);refreshChats();}else if(type=="chats"||type=="presence"||type=="read"||type=="delivered")refreshChats();}
void Window::settings(){QDialog dialog(this);dialog.setWindowTitle("Настройки Волны Desktop");dialog.setMinimumWidth(420);auto layout=new QVBoxLayout(&dialog);layout->addWidget(label("Волна Native Desktop 0.1.0\nQt/C++ · компоненты Telegram Desktop\nСервер: "+_api->origin().toString(),"title"));auto dark=new QCheckBox("Ночная тема");dark->setChecked(QSettings().value("dark",true).toBool());layout->addWidget(dark);connect(dark,&QCheckBox::toggled,this,[this](bool value){QSettings().setValue("dark",value);_theme=Theme::load(value);_theme.apply(*qApp);renderMessages(true);});auto tray=new QCheckBox("Показывать иконку в трее");tray->setChecked(_tray&&_tray->isVisible());tray->setEnabled(_tray);layout->addWidget(tray);connect(tray,&QCheckBox::toggled,this,[this](bool value){QSettings().setValue("tray",value);if(_tray)_tray->setVisible(value);});layout->addWidget(label("Windows защищает сохранённый сеанс через DPAPI. Эта версия хранит аккаунт отдельно от установленного клиента Волны.","subtitle"));auto about=button("Исходный код и лицензии","about");layout->addWidget(about);connect(about,&QPushButton::clicked,&dialog,[this]{QMessageBox::information(this,"О клиенте","Нативный интерфейс Qt/C++ для протокола Волны.\nИспользованы палитры Telegram Desktop v6.3.3 (GPL-3.0-or-later) и QR-генератор из его зависимостей (MIT).\nЗвонки и голосовые: WebRTC Волны в Qt WebEngine.\nИсходный код: https://github.com/andluk87/volna/tree/main/desktop-native\nЭто самостоятельный клиент, не официальный Telegram.");});if(_userId){auto logout=button("Выйти из аккаунта","logout");layout->addWidget(logout);connect(logout,&QPushButton::clicked,&dialog,[this,&dialog]{if((_calls&&_calls->active())||_recording){error("Сначала завершите звонок или запись");return;}if(QMessageBox::question(this,"Выйти из аккаунта?","Переписка останется на сервере")!=QMessageBox::Yes)return;dialog.accept();_api->logout([this](ApiResult result){if(!result.ok())error(result.error);});});}auto close=new QDialogButtonBox(QDialogButtonBox::Close);layout->addWidget(close);connect(close,&QDialogButtonBox::rejected,&dialog,&QDialog::reject);dialog.exec();}
void Window::closeEvent(QCloseEvent *event){if(_quitting){event->accept();return;}if(_tray&&_tray->isVisible()){event->ignore();hide();presence();return;}if((_calls&&_calls->active())||_recording||_api->busy()){event->ignore();error("Завершите звонок или запись и дождитесь сохранения сеанса");return;}_quitting=true;presence();event->accept();}
void Window::changeEvent(QEvent *event){QMainWindow::changeEvent(event);if(event->type()==QEvent::WindowStateChange||event->type()==QEvent::ActivationChange)presence();}
